private static final ThreadLocal<UserContext> CTX = new ThreadLocal<>();

// 显式线程池：有界队列 + 自定义拒绝策略，禁用 Executors 固定工厂
ThreadPoolExecutor pool = new ThreadPoolExecutor(
    4, 8, 60L, TimeUnit.SECONDS,
    new ArrayBlockingQueue<>(200),
    r -> { Thread t = new Thread(r, "biz-ctx-pool"); t.setDaemon(true); return t; },
    new ThreadPoolExecutor.CallerRunsPolicy());

void handle(Request req) {
  pool.execute(() -> {
    try {
      CTX.set(buildContext(req));   // 绑定当前任务上下文
      doBusiness();                  // 任意深层方法可用 CTX.get()
    } finally {
      CTX.remove();                  // 必须清理：断 value 强引用，防泄漏 + 防串号
    }
  });
}

UserContext currentUser() { return CTX.get(); }
